__NUXT_JSONP__("/inclusion/columnas/como_fortalecer_la_perspectiva_de_genero_en_la_reforma_sobre_plataformas_digitales", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H){return {data:[{post:{slug:"como_fortalecer_la_perspectiva_de_genero_en_la_reforma_sobre_plataformas_digitales",title:"¿Cómo fortalecer la perspectiva de género en la reforma sobre plataformas digitales?",date:"2025-03-25T21:34:09.393Z",img:"https:\u002F\u002Fucarecdn.com\u002F162dcc2a-9b88-465b-8004-7d592449629d\u002F","img-alt":"Mujer repartidora",autor:"Ivette Pichardo, Ana Medina, Shaira Garduño y Néstor Genis",medio:u,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ffortalecer-perspectiva-genero-reforma-plataformas-digitales",category:i,extracto:"Para que la reforma a la Ley Federal del Trabajo sobre plataformas digitales sea verdaderamente justa e inclusiva no basta con reconocer la relación laboral; es imperativo garantizar que las mujeres puedan ejercer plenamente sus derechos, acceder a la seguridad social y trabajar en un entorno libre de violencia.",toc:[{id:v,depth:m,text:w},{id:x,depth:m,text:y},{id:z,depth:m,text:A}],body:{type:j,children:[{type:b,tag:e,props:{},children:[{type:a,value:"A finales del año pasado hubo un importante avance en materia de justicia laboral en México: la publicación en el Diario Oficial de la Federación de la reforma a la Ley Federal del Trabajo sobre "},{type:b,tag:d,props:{},children:[{type:a,value:"plataformas digitales."}]},{type:a,value:" Esta reforma reconoce la relación laboral entre las personas trabajadoras y las plataformas digitales, a quienes antes se les reconocía como “socias”."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Este es un gran paso para la "},{type:b,tag:d,props:{},children:[{type:a,value:"justicia laboral"}]},{type:a,value:"; sin embargo, para que la reforma sea verdaderamente justa e inclusiva, "},{type:b,tag:d,props:{},children:[{type:a,value:"es esencial fortalecer la perspectiva de género"}]},{type:a,value:" en su implementación. Si bien la reforma sí menciona la inclusión de la perspectiva de género, no queda del todo claro cómo se aterrizará. En este sentido, para su efectiva incorporación, se deben considerar las necesidades y desafíos específicos que enfrentan las mujeres en este sector."}]},{type:a,value:c},{type:b,tag:n,props:{id:v},children:[{type:b,tag:g,props:{href:"#protocolos-de-prevenci%C3%B3n-y-atenci%C3%B3n-a-la-violencia-de-g%C3%A9nero",ariaHidden:o,tabIndex:p},children:[{type:b,tag:q,props:{className:[r,s]},children:[]}]},{type:b,tag:d,props:{},children:[{type:a,value:w}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Las mujeres que trabajan en plataformas digitales a menudo enfrentan acoso, discriminación y violencia de género. Las más comunes son comentarios inapropiados (bromas sexistas, comentarios sobre su apariencia, etc.), insinuaciones sexuales y contacto físico no deseado. La gran mayoría de los actos son cometidos por los clientes, pero en algunas ocasiones también por compañeros trabajadores."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"La reforma establece en los artículos 291K y 291R la obligación de las plataformas de establecer protocolos para atender estas problemáticas. Para que sean efectivos, es crucial que se consideren los siguientes aspectos:"}]},{type:a,value:c},{type:b,tag:t,props:{},children:[{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Incluir a las trabajadoras en el diseño de los mecanismos de prevención y atención"}]},{type:a,value:", asegurando que las medidas sean realmente útiles y relevantes para ellas. Por ejemplo, con la verificación periódica de los usuarios con identificación oficial, mantener el número de celular encriptado y opciones para sancionar a usuarios con comportamientos inapropiados."}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Contemplar riesgos y medidas de atención diferenciadas entre conductoras y repartidoras"}]},{type:a,value:", reconociendo que las mujeres enfrentan diferentes tipos de violencia y discriminación según su tipo de trabajo."}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Consultar las estrategias que las organizaciones de trabajadoras han desarrollado para cuidarse entre ellas"}]},{type:a,value:", incorporando el conocimiento y las experiencias de quienes han estado trabajando en la protección de las mujeres en el sector."}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Reconocer que la existencia de protocolos en sí misma no garantiza su efectividad."}]},{type:a,value:" Es fundamental que se establezcan mecanismos de vigilancia claros para asegurar que estos protocolos se implementen adecuadamente y que las empresas rindan cuentas por su cumplimiento."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:n,props:{id:x},children:[{type:b,tag:g,props:{href:"#acceso-y-pleno-ejercicio-de-prestaciones-laborales",ariaHidden:o,tabIndex:p},children:[{type:b,tag:q,props:{className:[r,s]},children:[]}]},{type:b,tag:d,props:{},children:[{type:a,value:y}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"La reforma establece que para acceder a todas las prestaciones de ley se deberá generar un salario mínimo mensual (8,475 pesos). Sin embargo, las mujeres enfrentan barreras adicionales para alcanzar este salario, como la "},{type:b,tag:d,props:{},children:[{type:a,value:"brecha salarial,"}]},{type:a,value:" relacionada con la carga de cuidados y la inseguridad que limita sus horarios y zonas de trabajo. Además, el dinamismo económico de la región en la que trabajan es otro factor a considerar. Para garantizar el acceso y pleno ejercicio de las prestaciones laborales para las mujeres, es necesario:"}]},{type:a,value:c},{type:b,tag:t,props:{},children:[{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Considerar la brecha salarial y la carga de cuidados en el diseño de las políticas"}]},{type:a,value:", implementando medidas que compensen estas desigualdades y faciliten el acceso a las prestaciones para las mujeres."}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Asegurar la seguridad social para mujeres embarazadas"}]},{type:a,value:", incluyendo una excepción explícita en la reforma para que las mujeres embarazadas no pierdan su acceso a la seguridad social durante su periodo de inactividad laboral, pues actualmente se contempla que si una persona deja de tener actividad por 30 días naturales se dará por terminada la relación laboral automáticamente."}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Considerar como la gestión algorítmica puede influir en la generación de desigualdades,"}]},{type:a,value:" en aspectos como la brecha salarial y, consecuentemente, el acceso a la seguridad social. Por ello la transparencia algorítmica es crucial para garantizar que no se incurra en una gestión discriminatoria por razones de género."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:n,props:{id:z},children:[{type:b,tag:g,props:{href:"#incorporar-la-perspectiva-de-g%C3%A9nero-desde-el-dise%C3%B1o-de-la-prueba-piloto",ariaHidden:o,tabIndex:p},children:[{type:b,tag:q,props:{className:[r,s]},children:[]}]},{type:b,tag:d,props:{},children:[{type:a,value:A}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"La prueba piloto que se implementará en los próximos meses ayudará a comprender mejor la dinámica laboral del sector y desarrollar reglas para su incorporación al IMSS. Esta debe considerar la perspectiva de género desde su diseño. Para ello, es fundamental."}]},{type:a,value:c},{type:b,tag:t,props:{},children:[{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Generar información desagregada por género sobre la tasa de participación, horas de conexión, ingresos, accidentes y riesgos laborales"}]},{type:a,value:", entre otros indicadores, para comprender las dinámicas específicas del trabajo de las mujeres en el sector y diseñar políticas que respondan a sus necesidades."}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"Garantizar la participación de mujeres en las mesas de trabajo para el diseño, seguimiento y ajustes de la reforma"}]},{type:a,value:", asegurando que las voces y perspectivas de las mujeres estén representadas en el proceso."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Esta reforma laboral sienta un precedente crucial para establecer condiciones de trabajo dignas. Además, impulsa la transformación de los esquemas laborales y de seguridad social en sectores precarizados, abriendo un debate político y económico sobre la distribución justa de las ganancias y la construcción de un mercado laboral equitativo que reduzca las brechas de género."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Sin embargo, su verdadero éxito dependerá de su implementación con perspectiva de género. No basta con reconocer la relación laboral; es imperativo garantizar que las mujeres puedan ejercer plenamente sus derechos, acceder a la seguridad social y trabajar en un entorno libre de violencia. La reforma ofrece una oportunidad histórica para construir un futuro laboral más justo e igualitario, pero solo se materializará si se toman medidas concretas para abordar las desigualdades que enfrentan las trabajadoras en las plataformas digitales."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Para asegurar que la promesa de justicia laboral se convierta en una realidad para todas las personas, es crucial la colaboración entre el Estado, las empresas y la sociedad civil. En este proceso, las colectivas de trabajadoras y las organizaciones aliadas jugarán un papel fundamental, manteniéndose unidas para vigilar, impulsar y exigir que la reforma se implemente de la mejor manera y cumpla el cometido de trabajo digno para todas."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"*"}]},{type:a,value:" "},{type:b,tag:d,props:{},children:[{type:a,value:"Ivette Pichardo"}]},{type:a,value:" forma parte de la colectiva Conductores por Juárez, "},{type:b,tag:d,props:{},children:[{type:a,value:"Ana Medina"}]},{type:a,value:" de Lady Drivers, "},{type:b,tag:d,props:{},children:[{type:a,value:"Shaira Garduño"}]},{type:a,value:" de la Unión Nacional de Trabajadores por Aplicación y "},{type:b,tag:d,props:{},children:[{type:a,value:"Néstor Genis"}]},{type:a,value:" ("},{type:b,tag:g,props:{href:"https:\u002F\u002Fx.com\u002FGenisNestor",rel:[B,C,D],target:E},children:[{type:a,value:"@GenisNestor"}]},{type:a,value:") es coordinador de Inclusión y Desarrollo Sostenible en Ethos Innovación en Políticas Públicas ("},{type:b,tag:g,props:{href:"https:\u002F\u002Fx.com\u002FEthosInnovacion",rel:[B,C,D],target:E},children:[{type:a,value:"@EthosInnovacion"}]},{type:a,value:")."}]}]},dir:k,path:"\u002Fcolumnas\u002Fcomo_fortalecer_la_perspectiva_de_genero_en_la_reforma_sobre_plataformas_digitales",extension:l,createdAt:"2025-04-23T06:21:15.368Z",updatedAt:"2025-04-23T06:21:15.369Z"},columnas:[{slug:"arriba_las_sirenas_negras",title:"¡Arriba las sirenas negras!",date:"2023-03-21T17:00:05.207Z",img:"https:\u002F\u002Fucarecdn.com\u002F4a69a88d-6432-46c0-9f15-96253c5a619b\u002F","img-alt":"Inclusión",autor:"Berenice Valencia",medio:u,link:"https:\u002F\u002Fwww.animalpolitico.com\u002Fanalisis\u002Finvitades\u002Farriba-las-sirenas-negras",category:i,extracto:"El racismo no se reduce a discriminación y para eliminarlo no es suficiente la representación en medios. El racismo es también la distribución desigual de recursos y poder que clasifica a las personas de acuerdo a ciertas características que se han construido socialmente como “razas”.",toc:[],body:{type:j,children:[{type:b,tag:e,props:{},children:[{type:a,value:"En septiembre del año pasado, "},{type:b,tag:d,props:{},children:[{type:a,value:"Disney"}]},{type:a,value:" estrenó el trailer de su nueva versión de "},{type:b,tag:d,props:{},children:[{type:a,value:"La Sirenita"}]},{type:a,value:", donde Halle Bailey, una actriz negra, interpreta a la sirena Ariel. Con las primeras imágenes de la "},{type:b,tag:d,props:{},children:[{type:a,value:"película"}]},{type:a,value:" llegaron críticas simplonas de adultos indignados por un "},{type:b,tag:h,props:{},children:[{type:a,value:"casting"}]},{type:a,value:" que, decían, arruinaba sus infancias, y por videos de niñas emocionadas por verse reflejadas en Ariel. También surgieron artículos explicando acertadamente por qué la indignación de esos adultos viene del racismo y por qué es importante que las infancias negras se vean representadas en la pantalla grande."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Meses antes, cuando no había trailer pero ya sabíamos que Halle Bailey sería Ariel, se volvió popular el video de una niña a quien le preguntan en la calle qué opina al respecto y ella, sin inmutarse, contesta: “no las tenemos que discriminar, arriba las "},{type:b,tag:d,props:{},children:[{type:a,value:"sirenas negras"}]},{type:a,value:"”. Me parece un gran mensaje para este "},{type:b,tag:d,props:{},children:[{type:a,value:"Día Internacional de la Eliminación de la Discriminación Racial"}]},{type:a,value:". No es suficiente con no discriminar, hay que celebrar la representación de la diversidad. Sin embargo, yo agregaría que es importante llevar nuestras conversaciones sobre racismo más allá de la discriminación y la representación."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"En México, hasta hace un par de años las conversaciones sobre racismo eran prácticamente inexistentes. La idea de que México es clasista, pero no racista (como si eso fuera aceptable) no se cuestionaba. Recientemente se ha popularizado el cuestionar, al menos, la falta de representación en medios. Esto se debe, en buena medida, a "},{type:b,tag:d,props:{},children:[{type:a,value:"Poder Prieto"}]},{type:a,value:", una colectiva conformada principalmente por actrices y actores que han denunciado la discriminación racial en la industria del entretenimiento. Actores con mucha visibilidad como Tenoch Huerta y Maya Zapata han impulsado las discusiones sobre por qué en casi todos los programas de televisión, películas y comerciales mexicanos, los actores son blancos."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Que los protagonistas de nuestras historias sean siempre blancos en un país como México -donde el 19 % de la población se autoidentifica como indígena, el 2 % como afrodescendiente y el 67 % autoclasifica su piel en tonos morenos- muestra una evidente discriminación racial. Discriminar significa tratar de forma diferenciada y despreciativa a una persona o grupo debido a nuestros prejuicios respecto a ese grupo. En este caso, es lo que sucede no solamente durante los "},{type:b,tag:h,props:{},children:[{type:a,value:F}]},{type:a,value:" sino en las salas donde se escriben los guiones y detrás de las cámaras de las producciones mediáticas. México y el mundo se nos presentan como si sólo existieran cierto tipo de personas, como si nuestra empatía y nuestras narrativas sólo pudieran tratarse de gente blanca. Nos presentan la blanquitud como realidad única y como aspiración."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"La discriminación, por supuesto, es un problema grave. Sin embargo, el racismo no se reduce a discriminación y para eliminarlo no es suficiente la representación en medios. El racismo no sólo es que no aparezcan personas negras o de pueblos originarios en la portada de Quien. El racismo (también) es la distribución desigual de recursos y poder que clasifica a las personas de acuerdo a ciertas características que se han construido socialmente (sin fundamento biológico, por cierto) como “razas”."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Entonces, el racismo está en los "},{type:b,tag:h,props:{},children:[{type:a,value:F}]},{type:a,value:" de Televisa, sí, pero también está en el hecho de que, en México, las personas afrodescendientes tienen un mayor porcentaje de analfabetismo y menos acceso al agua entubada. Está en el sistema de salud y de justicia cuando no garantizan el acceso a sus servicios en lenguas de pueblos originarios. El racismo está en la falta de datos sobre la situación económica de la población afrodescendiente y en el despojo y contaminación de las tierras de pueblos originarios."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Existen diversos colectivos como Copera, Afrontera, Kumoontun, entre otras, que nos proporcionan claves para expandir la conversación sobre el racismo y para exigir no sólo cambios de comportamiento individual sino políticas públicas que contribuyan a eliminarlo. La discriminación racial no se terminará si no atendemos el racismo estructural. Así que, celebremos a las sirenas, superheroínas y protagonistas negras y de pueblos originarios, pero hagámoslo sabiendo que la representación no soluciona la desigualdad estructural. Debemos exigir más."}]}]},dir:k,path:"\u002Fcolumnas\u002Farriba_las_sirenas_negras",extension:l,createdAt:"2023-06-19T05:11:57.400Z",updatedAt:"2023-05-30T23:46:33.649Z"},{slug:"caravana_migrante_el_mas_reciente_reto_de_politica_exterior",title:"Caravana migrante, el más reciente reto de política exterior",date:"2019-01-21T20:32:25.569Z",img:"https:\u002F\u002Fucarecdn.com\u002Fee24c242-c206-4976-a9c9-0bec75c19113\u002F",autor:"Ana Paula Sandoval",medio:"Expansion ",link:"https:\u002F\u002Fexpansion.mx\u002Fopinion\u002F2019\u002F01\u002F21\u002Fopinion-caravana-migrante-el-mas-reciente-reto-de-politica-exterior",category:i,extracto:G,toc:[],body:{type:j,children:[{type:b,tag:e,props:{},children:[{type:b,tag:h,props:{},children:[{type:a,value:"López Obrador tiene una gran oportunidad de convertirse en un ejemplo mundial de cómo enfrentarse y resolver una problemática que ha caracterizado al siglo XXI, opina Ana Paula Sandoval."}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:G}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"En esa ocasión, los migrantes centroamericanos se enfrentaron a la violencia y represión de parte de la policía mexicana que con equipos antimotines les impidió –por poco tiempo- el paso, dando lugar a una ola de violencia. Esta acción fue fuertemente criticada señalando que México accedió a hacer el “"},{type:b,tag:h,props:{},children:[{type:a,value:"trabajo sucio"}]},{type:a,value:"” a Estados Unidos, país que ha tomado una postura extremadamente crítica y restrictiva ante estos fenómenos migratorios."}]}]},dir:k,path:"\u002Fcolumnas\u002Fcaravana_migrante_el_mas_reciente_reto_de_politica_exterior",extension:l,createdAt:"2023-06-19T05:11:57.476Z",updatedAt:"2022-08-22T22:00:47.046Z"},{slug:"como_aumentar_la_productividad_en_mexico",title:"¿Cómo aumentar la productividad en México?",date:"2014-12-12T20:59:19.115Z",img:"https:\u002F\u002Fucarecdn.com\u002Fb0f9f150-1650-4570-bd56-b8aa1e6719f8\u002F",autor:"José Luis Chicoma, Eduardo Sierra",medio:" El punto sobre la i",link:"https:\u002F\u002Fmedia.wix.com\u002Fugd\u002F5a5f52_ea39ffab127545e589bd08be024e7b60.pdf",category:i,extracto:H,toc:[],body:{type:j,children:[{type:b,tag:e,props:{},children:[{type:a,value:H}]}]},dir:k,path:"\u002Fcolumnas\u002Fcomo_aumentar_la_productividad_en_mexico",extension:l,createdAt:"2023-06-19T05:11:57.536Z",updatedAt:"2022-08-22T22:00:47.047Z"}]}],fetch:{},mutations:[]}}("text","element","\n","strong","p","li","a","em","inclusion","root","\u002Fcolumnas",".md",3,"h3","true",-1,"span","icon","icon-link","ul","Animal Político","protocolos-de-prevención-y-atención-a-la-violencia-de-género","Protocolos de prevención y atención a la violencia de género","acceso-y-pleno-ejercicio-de-prestaciones-laborales","Acceso y pleno ejercicio de prestaciones laborales","incorporar-la-perspectiva-de-género-desde-el-diseño-de-la-prueba-piloto","Incorporar la perspectiva de género desde el diseño de la prueba piloto","nofollow","noopener","noreferrer","_blank","castings","El martes pasado una nueva caravana migrante, conformada inicialmente por unas 500 personas (y que actualmente supera las 2,000), partió de Honduras con miras de llegar a Estados Unidos en busca del sueño americano. Este episodio se repite después de que una primera caravana emprendiera su camino el 13 de octubre del año pasado.","La generación de mayor conocimiento, no sólo se traduce en mejores condiciones laborales, también genera efectos positivos en la economía.")));